private static void doService(Object infos) {
            // si recupera il cliente da servire
            Client client = infos as Client;
            // si fornisce il servizio al cliente
            Console.WriteLine("Début du service au client {0}", client.NumClient);
            // elaborazione del collegamento TcpClient
            try {
                using (TcpClient tcpClient = client.CanalTcp) {
                    using (NetworkStream networkStream = tcpClient.GetStream()) {
                        using (StreamReader reader = new StreamReader(networkStream)) {
                            using (StreamWriter writer = new StreamWriter(networkStream)) {
                                // flusso di uscita non bufferizzato
                                writer.AutoFlush = true;
                                // invio di un messaggio di benvenuto al cliente
                                writer.WriteLine("Bienvenue sur le serveur de calcul de l'impôt");
                                // ciclo di lettura richiesta/scrittura risposta
                                string demande = null;
                                bool serviceFini = false;
                                while (!serviceFini &amp;&amp; (demande = reader.ReadLine()) != null) {
                                    // monitoraggio console
                                    if (echo) {
                                        Console.WriteLine("&lt;--- Client {0} : {1}", client.NumClient, demande);
                                    }
                                    // analisi della richiesta
                                    demande = demande.Trim().ToLower();
                                    // richiesta vuota?
                                    if (demande.Length == 0) {
                                        // richiesta errata
                                        writeClient(writer,client.NumClient,"Commande non reconnue. Utilisez la commande aide.");
                                        return;
                                    }

                                    // scomposizione della richiesta in campi
                                    string[] champs = Regex.Split(demande, @"\s+");
                                    // analisi
                                    switch (champs[0].ToLower()) {
                                        case "aide":
                                            writeClient(writer, client.NumClient, "Commandes acceptées\n1-aide\n2-impot marié(O/N) nbEnfants salaireAnnuel\n3-aurevoir");
                                            break;
                                        case "impot":
                                            // calcolo dell'imposta
                                            writeClient(writer, client.NumClient, calculImpot(writer, client.NumClient, champs));
                                            break;
                                        case "aurevoir":
                                            serviceFini = true;
                                            writeClient(writer, client.NumClient, "Au revoir...");
                                            break;
                                        default:
                                            writeClient(writer, client.NumClient, "Commande non reconnue. Utilisez la commande aide.");
                                            break;
                                    }
                                }
                            }
                        }
                    }
                }
            } catch (Exception e) {
                // errore
                Console.WriteLine("L'erreur suivante s'est produite lors du service au client {0} : {1}", client.NumClient, e.Message);
            } finally {
                Console.WriteLine("Fin du service au client {0}", client.NumClient);
            }
        }

        private static void writeClient(StreamWriter writer, int numClient, string message) {
            // output console?
            if (echo) {
                Console.WriteLine("---&gt; Client {0} : {1}", numClient, message);
            }
            // invio messaggio al cliente
            writer.WriteLine(message);
}
</code></pre> <p>Anche in questo caso, il codice è simile a quello del server di eco esaminato nel paragrafo 11.6.1. Commentiamo solo le differenze:</p> <ul> <li>riga 15: una volta che il cliente si è connesso, il server gli invia un messaggio di benvenuto.   </li> <li>righe 19-52: il ciclo di lettura dei comandi del client. Il ciclo si interrompe quando il client invia il comando "aurevoir".   </li> <li>riga 27: caso di comando vuoto   </li> <li>riga 34: la richiesta viene scomposta in campi per essere analizzata   </li> <li>riga 37: comando aide: il cliente richiede l'elenco dei comandi autorizzati   </li> <li>riga 40: comando impot: il cliente richiede il calcolo dell’imposta. Si risponde con il messaggio restituito dal metodo calculImpot, che descriveremo in dettaglio tra poco.   </li> <li>riga 44: comando aurevoir: il cliente indica di aver terminato.   </li> <li>riga 45: ci si prepara a uscire dal ciclo di lettura delle richieste del cliente (righe 19-52)   </li> <li>riga 46: si risponde al cliente con un messaggio di saluto   </li> <li>riga 48: comando non corretto. Si invia al cliente un messaggio di errore.   </li> </ul> <p>L'elaborazione dell'ordine impot è gestita dal seguente metodo calculImpot:</p> <pre><code>
private static string calculImpot(StreamWriter writer, int numClient, string[] champs) {
            // richiesta calcolo stato civile (S/N) nbEnfants salaireAnnuel
            // sono necessari 4 campi
            if (champs.Length != 4) {
                return "Commande calcul incorrecte. Utilisez la commande aide.";
            }
            // campi [1]
            string marié = champs[1];
            if (marié != "o" &amp;&amp; marié != "n") {
                return "Commande calcul incorrecte. Utilisez la commande aide.";
            }
            // campi [2]
            int nbEnfants;
            if (!int.TryParse(champs[2], out nbEnfants)) {
                return "Commande calcul incorrecte. Utilisez la commande aide.";
            }
            // campi [3]
            int salaireAnnuel;
            if (!int.TryParse(champs[3], out salaireAnnuel)) {
                return "Commande calcul incorrecte. Utilisez la commande aide.";
            }
            // Va bene - si calcola l'imposta
            int impot = 0;
            try {
                impot = metier.CalculerImpot(marié == "o", nbEnfants, salaireAnnuel);
                return impot.ToString();
            } catch (Exception ex) {
                return ex.Message;
            }
        }
</code></pre> <ul> <li>riga 1: il metodo riceve come terzo parametro l’array dei campi dell’ordine impot. Se quest’ultimo è stato formulato correttamente, ha la forma «reddito coniugato nbEnfants salaireAnnuel». Il metodo restituisce come risultato la risposta da inviare al cliente.   </li> <li>riga 4: si verifica che l'ordine abbia 4 campi   </li> <li>riga 8: si verifica che il campo marié sia valido   </li> <li>riga 14: si verifica che il campo nbEnfants sia valido   </li> <li>riga 19: si verifica che il campo salaireAnnuel sia valido   </li> <li>riga 25: l'imposta viene calcolata utilizzando il metodo CalculerImpot del livello [metier]. Si ricorda che questo livello è incapsulato in un DLL.   </li> <li>riga 26: se il livello [metier] ha restituito un risultato, questo viene restituito al cliente.   </li> <li>riga 28: se il livello [metier] ha generato un'eccezione, il messaggio relativo a tale eccezione viene restituito al client.   </li> </ul> <p></p>
